#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Account setup (#66, ADR 0008): the Neon Postgres database that holds
# Accounts, provisioned from the Vercel Marketplace, its schema
# (`pnpm db:migrate`), Better Auth's secret and address, the Admin allow-list
# and the GitHub sign-in apps Admins use (#67), and the Google and Apple
# sign-in apps, written to the Vercel project's Production (and Preview)
# environment and, for local development, to .env.local. docs/account-setup.md
# says what each setting is. It works in the website's own directory, apps/web
# (#63), where Next.js reads .env.local and `vercel link` links the saaliheen
# project, wherever it is run from.
#
#   apps/web/scripts/setup-accounts.sh
#
# The callback URLs the GitHub apps, the Google client and the Apple Services ID must list:
#   https://saaliheen.com/api/v1/auth/callback/github (a second GitHub app: http://localhost:3000/...)
#   https://saaliheen.com/api/v1/auth/callback/google (and http://localhost:3000/...)
#   https://saaliheen.com/api/v1/auth/callback/apple
#
# Production values are sent to Vercel only and never written locally, so a
# re-run asks for them again; local values are kept in .env.local.
# ACCOUNT_TEST_SIGN_IN is the site tests' switch only: this wizard never sets it.

cd "$(dirname "$0")/.."
ENV_FILE=".env.local"
PROD_URL="https://saaliheen.com"
LOCAL_URL="http://localhost:3000"
CALLBACK_PATH="/api/v1/auth/callback"
PULLED_ENV=".env.vercel-production.local" # scratch file, deleted right after use
VERCEL_ENVS=() # Vercel variables set this run, as NAME (environment)

# vercel_env NAME VALUE ENVIRONMENT [sensitive] sets NAME on the Vercel
# project's ENVIRONMENT (production or preview), replacing any value it had.
# The value goes over stdin, so it never shows in the process list.
vercel_env() {
  local name="$1" value="$2" environment="$3" flags=(--force --yes)
  [[ "${4:-}" == sensitive ]] && flags+=(--sensitive)
  local out
  if out=$(printf '%s' "$value" | vercel env add "$name" "$environment" "${flags[@]}" 2>&1); then
    VERCEL_ENVS+=("$name ($environment)")
    printf '  %s✓ set%s Vercel %s %s\n' "$GREEN" "$RESET" "$environment" "$name"
  else
    SKIPPED+=("Vercel $environment $name (vercel env add $name $environment)")
    warn "couldn't set Vercel $environment $name; set it later. Vercel said:"
    printf '%s\n' "$out" | tail -n 3 | sed 's/^/      /'
  fi
}

# required NAME: stop when the value the human was asked for is empty.
required() {
  [[ -n "${!1}" ]] && return
  printf '  %s✗ %s is empty; re-run the wizard when you have it.%s\n' "$RED" "$1" "$RESET"
  exit 1
}

# env_value FILE KEY: KEY's value in a dotenv FILE, without surrounding quotes.
env_value() {
  local line; line=$(grep -E "^${2}=" "$1" 2>/dev/null | tail -n1) || return 1
  line="${line#*=}"; line="${line%\"}"; line="${line#\"}"
  printf '%s' "$line"
}

# migrate URL: apply the Account schema to the Postgres database at URL.
migrate() {
  if DATABASE_URL="$1" pnpm db:migrate; then
    printf '  %s✓ migrated%s the Account tables\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("pnpm db:migrate against $2 (DATABASE_URL=... pnpm db:migrate in apps/web)")
    warn "pnpm db:migrate failed against $2; fix it and run it by hand (docs/account-setup.md)."
  fi
}

# apple_client_secret: the APPLE_CLIENT_SECRET JWT, signed ES256 with the .p8
# key at APPLE_KEY_PATH, from APPLE_TEAM_ID, APPLE_KEY_ID and APPLE_CLIENT_ID.
# It expires in 180 days; Apple allows at most six months.
apple_client_secret() {
  TEAM="$APPLE_TEAM_ID" KID="$APPLE_KEY_ID" CID="$APPLE_CLIENT_ID" P8="$APPLE_KEY_PATH" node -e '
    const crypto = require("crypto"), fs = require("fs");
    const part = (o) => Buffer.from(JSON.stringify(o)).toString("base64url");
    const now = Math.floor(Date.now() / 1000);
    const head = part({ alg: "ES256", kid: process.env.KID });
    const body = part({ iss: process.env.TEAM, iat: now, exp: now + 180 * 86400, aud: "https://appleid.apple.com", sub: process.env.CID });
    const key = fs.readFileSync(process.env.P8);
    const sig = crypto.sign("sha256", Buffer.from(head + "." + body), { key, dsaEncoding: "ieee-p1363" }).toString("base64url");
    console.log(head + "." + body + "." + sig);'
}

TOTAL_STAGES=13

# Stages 1, 2 and 12 need the Vercel CLI, so check for it before anything is
# registered. It's often installed under nvm, which a fresh shell may not have loaded.
if ! command -v vercel >/dev/null 2>&1; then
  printf '  %s✗ The Vercel CLI (vercel) is not on PATH.%s\n' "$RED" "$RESET"
  note "Install it (npm install --global vercel) or load the Node it's installed under"
  note "(e.g. 'nvm use 24'), check 'vercel whoami' works, then re-run the wizard."
  exit 1
fi
if ! vercel whoami >/dev/null 2>&1; then
  printf '  %s✗ The Vercel CLI is not signed in.%s\n' "$RED" "$RESET"
  note "Run 'vercel login', then re-run the wizard."
  exit 1
fi
for tool in node pnpm openssl; do
  command -v "$tool" >/dev/null 2>&1 && continue
  printf '  %s✗ %s is not on PATH; install it, then re-run the wizard.%s\n' "$RED" "$tool" "$RESET"
  exit 1
done

if [[ ! -f .vercel/project.json ]]; then
  warn "This checkout isn't linked to Vercel (no .vercel/project.json)."
  confirm "Run 'vercel link' now? (pick the saaliheen project)" || { note "Run it from a linked checkout."; exit 1; }
  vercel link
fi

banner "Saaliheen Accounts: Neon, GitHub (Admins), Google and Apple sign-in"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Neon: a Postgres database from the Vercel Marketplace"
say "Accounts live in Neon Postgres (ADR 0008). Neon is installed from the Vercel"
say "Marketplace, which bills it through Vercel and sets DATABASE_URL on the project."
open_url "https://vercel.com/marketplace/neon"
step "Click Install (or 'Add Integration'), pick your Vercel team, then Continue."
step "Plan: Free is enough to start · Region: the one nearest the site's Vercel functions (e.g. Washington, D.C., iad1)."
step "Database name: saaliheen · Create."
step "Connect Project → the saaliheen project · Environments: Production, Preview and Development."
note "    Leave the custom prefix empty, so the variable is called exactly DATABASE_URL."
note "    Optional: tick 'Create database branch for deployment' for Previews, so a"
note "    Preview never writes to production's Accounts."
step "Click Connect."
pause "Press Enter once Storage → saaliheen shows the project connected"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Neon: create the Account tables in production"
say "Pulling the Production variables to a scratch file to read DATABASE_URL,"
say "then running 'pnpm db:migrate' against it. The scratch file is deleted straight after."
PROD_DATABASE_URL=""
if vercel env pull "$PULLED_ENV" --environment=production --yes >/dev/null 2>&1; then
  PROD_DATABASE_URL=$(env_value "$PULLED_ENV" DATABASE_URL || true)
fi
rm -f "$PULLED_ENV"
if [[ -z "$PROD_DATABASE_URL" ]]; then
  warn "Couldn't read DATABASE_URL from Vercel (not connected yet, or stored as sensitive)."
  note "    Copy it from Vercel → Storage → saaliheen → .env.local tab (Show secret),"
  note "    or from the Neon console → Connect. It starts postgresql://"
  ask_secret PROD_DATABASE_URL "Paste production's DATABASE_URL:"
  required PROD_DATABASE_URL
fi
note "    host: $(printf '%s' "$PROD_DATABASE_URL" | sed -E 's#^[^@]*@([^/:?]*).*#\1#')"
if confirm "Run pnpm db:migrate against production's database now?"; then
  migrate "$PROD_DATABASE_URL" "production's database"
else
  SKIPPED+=("pnpm db:migrate against production's database")
fi
note "Run it again (same command) whenever a release changes the Account schema."
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Neon: a database for local development"
say "Local development needs its own DATABASE_URL in $ENV_FILE. Use a Neon branch"
say "of the database (Neon console → Branches → Create branch, e.g. 'dev'), so local"
say "sign-ins never touch production's Accounts. Any other Postgres works too."
open_url "https://console.neon.tech/app/projects"
step "Open the saaliheen project → Branches → Create branch 'dev' (from main)."
step "Connect → branch dev → copy the connection string."
if confirm "Set a local DATABASE_URL now?"; then
  ask_secret DATABASE_URL "Paste the local DATABASE_URL:"
  required DATABASE_URL
  write_env DATABASE_URL "$DATABASE_URL"
  if confirm "Run pnpm db:migrate against it now?"; then migrate "$DATABASE_URL" "the local database"; fi
else
  SKIPPED+=("local DATABASE_URL in $ENV_FILE, then pnpm db:migrate")
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Better Auth: secret and site address"
say "BETTER_AUTH_SECRET signs and encrypts Account sessions. Generating one for"
say "production, one for Previews and one for local development."
PROD_BETTER_AUTH_SECRET=$(openssl rand -base64 32)
PREVIEW_BETTER_AUTH_SECRET=$(openssl rand -base64 32)
BETTER_AUTH_SECRET=$(_existing BETTER_AUTH_SECRET || true)
if [[ ${#BETTER_AUTH_SECRET} -lt 32 ]]; then
  BETTER_AUTH_SECRET=$(openssl rand -base64 32)
  write_env BETTER_AUTH_SECRET "$BETTER_AUTH_SECRET"
else
  note "Keeping the local BETTER_AUTH_SECRET already in $ENV_FILE."
fi
note "Production gets a fresh secret on every run, which signs every reader out."
say ""
say "BETTER_AUTH_URL is the site's address, used to build the callback URLs:"
note "    Production: $PROD_URL · local: $LOCAL_URL"
note "    Previews get none: there the address is the one the browser asked for."
write_env BETTER_AUTH_URL "$LOCAL_URL"
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Admins: the Admin allow-list"
say "Admin is a role an Account holds: its verified email is on the Admin allow-list,"
say "checked on every request. Only those emails may sign in with GitHub."
say "Separate them with commas."
note "Use the email that is primary and verified on GitHub, and the Google account's email."
ask ADMIN_ALLOW_LIST "Admin emails (comma-separated):"
required ADMIN_ALLOW_LIST
write_env ADMIN_ALLOW_LIST "$ADMIN_ALLOW_LIST"
pause "Press Enter to continue"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub: OAuth app for production (Admins only)"
say "Admins can sign in with GitHub on the Sign-in page's Admin entry. A GitHub OAuth app"
say "allows exactly one callback URL, so production and local development each need their own."
say "An existing 'Saaliheen Admin' app can be reused: change its callback URL to the one below."
open_url "https://github.com/settings/applications/new"
step "Application name: Saaliheen · Homepage URL: $PROD_URL"
step "Authorization callback URL: $PROD_URL$CALLBACK_PATH/github"
step "Leave 'Enable Device Flow' unticked, then click Register application (or Update application)."
step "Copy the Client ID shown at the top of the app's page."
ask PROD_GITHUB_CLIENT_ID "Paste the production Client ID:"
required PROD_GITHUB_CLIENT_ID
step "Click 'Generate a new client secret', then copy it (GitHub shows it only once)."
ask_secret PROD_GITHUB_CLIENT_SECRET "Paste the production client secret:"
required PROD_GITHUB_CLIENT_SECRET

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "GitHub: OAuth app for local development"
say "Now a second app, for $LOCAL_URL."
open_url "https://github.com/settings/applications/new"
step "Application name: Saaliheen (local) · Homepage URL: $LOCAL_URL"
step "Authorization callback URL: $LOCAL_URL$CALLBACK_PATH/github"
step "Click Register application (or Update application), then copy the Client ID."
ask GITHUB_CLIENT_ID "Paste the local Client ID:"
required GITHUB_CLIENT_ID
step "Click 'Generate a new client secret', then copy it."
ask_secret GITHUB_CLIENT_SECRET "Paste the local client secret:"
required GITHUB_CLIENT_SECRET
write_env GITHUB_CLIENT_ID "$GITHUB_CLIENT_ID"
write_env GITHUB_CLIENT_SECRET "$GITHUB_CLIENT_SECRET"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Google: OAuth client"
say "Readers and Admins sign in with Google through an OAuth client in Google Cloud."
say "An existing client (such as the old 'Saaliheen Admin' one) can be reused:"
say "add the Account redirect URIs to it. Otherwise create a new Web client."
note "    (No Google Auth Platform yet? Follow 'Google' in docs/account-setup.md first:"
note "    branding with ${PROD_URL#https://} as an authorised domain, audience External, published.)"
open_url "https://console.cloud.google.com/auth/clients"
step "Open the 'Saaliheen Admin' client to reuse it, or Create client → Web application · Name: Saaliheen."
step "Authorized JavaScript origins → add both:"
note "    $PROD_URL"
note "    $LOCAL_URL"
step "Authorized redirect URIs → add both (an old /api/auth/callback/google one can go):"
note "    $PROD_URL$CALLBACK_PATH/google"
note "    $LOCAL_URL$CALLBACK_PATH/google"
step "Save (or Create). Copy the Client ID and a Client secret."
note "    Reusing a client whose secret you no longer have? Add secret, then copy the new one."
ask GOOGLE_CLIENT_ID "Paste the Client ID (ends .apps.googleusercontent.com):"
required GOOGLE_CLIENT_ID
ask_secret GOOGLE_CLIENT_SECRET "Paste the Client secret:"
required GOOGLE_CLIENT_SECRET
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Apple: App ID with Sign in with Apple"
say "Sign in with Apple needs a paid Apple Developer Program membership."
say "First an App ID that has the Sign in with Apple capability."
open_url "https://developer.apple.com/account/resources/identifiers/add/bundleId"
step "App IDs → Continue · Type: App → Continue."
step "Description: Saaliheen · Bundle ID (Explicit): com.saaliheen.app (or your own reverse-domain id)."
step "Capabilities → tick Sign in with Apple (Enable as a primary App ID) → Continue → Register."
step "Copy your Team ID, the 10 characters at the top right under your name (also on Membership details)."
ask APPLE_TEAM_ID "Paste the Team ID:"
required APPLE_TEAM_ID

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Apple: Services ID, domain and return URL"
say "The Services ID is the web sign-in's identity: its identifier is APPLE_CLIENT_ID."
open_url "https://developer.apple.com/account/resources/identifiers/add/serviceId"
step "Services IDs → Continue · Description: Saaliheen · Identifier: com.saaliheen.signin → Register."
step "Open the new Services ID → tick Sign in with Apple → Configure:"
note "    Primary App ID: the App ID from the previous stage"
note "    Domains and Subdomains: ${PROD_URL#https://}"
note "    Return URLs: $PROD_URL$CALLBACK_PATH/apple"
step "Next → Done → Continue → Save."
note "    Apple accepts only https return URLs on a real domain: Sign in with Apple works"
note "    on production, never on localhost or a Preview address."
ask APPLE_CLIENT_ID "Paste the Services ID identifier (e.g. com.saaliheen.signin):"
required APPLE_CLIENT_ID
write_env APPLE_CLIENT_ID "$APPLE_CLIENT_ID"

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Apple: signing key and the client secret"
say "Apple's client secret is a JWT you sign with a private key (.p8) from Apple."
open_url "https://developer.apple.com/account/resources/authkeys/add"
step "Key Name: Saaliheen Sign in with Apple · tick Sign in with Apple → Configure →"
note "    Primary App ID: the App ID from stage 6 → Save → Continue → Register."
step "Download the key (Apple lets you download it only once) and copy its Key ID."
ask APPLE_KEY_ID "Paste the Key ID (10 characters):"
required APPLE_KEY_ID
latest_p8=$(ls -t "$HOME"/Downloads/AuthKey_*.p8 2>/dev/null | head -n1 || true)
[[ -n "$latest_p8" ]] && note "    Newest download: $latest_p8"
ask APPLE_KEY_PATH "Path to the .p8 file${latest_p8:+ [Enter for the newest download]}:"
[[ -z "$APPLE_KEY_PATH" && -n "$latest_p8" ]] && APPLE_KEY_PATH="$latest_p8"
required APPLE_KEY_PATH
APPLE_KEY_PATH="${APPLE_KEY_PATH/#\~/$HOME}"
if [[ ! -f "$APPLE_KEY_PATH" ]] || ! grep -q -- '-----BEGIN PRIVATE KEY-----' "$APPLE_KEY_PATH"; then
  printf '  %s✗ %s is not a .p8 key (no BEGIN PRIVATE KEY line).%s\n' "$RED" "$APPLE_KEY_PATH" "$RESET"; exit 1
fi
if ! APPLE_CLIENT_SECRET=$(apple_client_secret); then
  printf '  %s✗ Could not sign the client secret with %s.%s\n' "$RED" "$APPLE_KEY_PATH" "$RESET"; exit 1
fi
write_env APPLE_CLIENT_SECRET "$APPLE_CLIENT_SECRET"
APPLE_SECRET_EXPIRES=$(node -e 'console.log(new Date(Date.now() + 180 * 86400e3).toISOString().slice(0, 10))')
warn "APPLE_CLIENT_SECRET expires on $APPLE_SECRET_EXPIRES (Apple allows at most 6 months)."
note "    Before then, re-run this wizard (or generate a new one: docs/account-setup.md)"
note "    and redeploy, or Sign in with Apple stops working. Put a reminder in your calendar."
note "    Keep the .p8 somewhere safe (a password manager), not in the repo."
pause "Press Enter to continue"

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Vercel: Production and Preview environment variables"
say "DATABASE_URL is already on the project, from the Neon integration."
say "Production gets, replacing any values already there:"
note "    BETTER_AUTH_URL=$PROD_URL, BETTER_AUTH_SECRET (sensitive)"
note "    ADMIN_ALLOW_LIST=$ADMIN_ALLOW_LIST"
note "    GITHUB_CLIENT_ID=$PROD_GITHUB_CLIENT_ID, GITHUB_CLIENT_SECRET (sensitive)"
note "    GOOGLE_CLIENT_ID=$GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET (sensitive)"
note "    APPLE_CLIENT_ID=$APPLE_CLIENT_ID, APPLE_CLIENT_SECRET (sensitive)"
say "Preview gets the same, with its own BETTER_AUTH_SECRET and no BETTER_AUTH_URL."
note "    GitHub, Google and Apple refuse a Preview's changing address, so sign-in is checked on production."
note "    ACCOUNT_TEST_SIGN_IN is never set on Vercel."
if confirm "Set them on Vercel Production now?"; then
  vercel_env BETTER_AUTH_URL "$PROD_URL" production
  vercel_env BETTER_AUTH_SECRET "$PROD_BETTER_AUTH_SECRET" production sensitive
  vercel_env ADMIN_ALLOW_LIST "$ADMIN_ALLOW_LIST" production
  vercel_env GITHUB_CLIENT_ID "$PROD_GITHUB_CLIENT_ID" production
  vercel_env GITHUB_CLIENT_SECRET "$PROD_GITHUB_CLIENT_SECRET" production sensitive
  vercel_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID" production
  vercel_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET" production sensitive
  vercel_env APPLE_CLIENT_ID "$APPLE_CLIENT_ID" production
  vercel_env APPLE_CLIENT_SECRET "$APPLE_CLIENT_SECRET" production sensitive
else
  SKIPPED+=("Vercel Production variables (re-run the wizard)")
fi
if confirm "Set them on Vercel Preview too?"; then
  vercel_env BETTER_AUTH_SECRET "$PREVIEW_BETTER_AUTH_SECRET" preview sensitive
  vercel_env ADMIN_ALLOW_LIST "$ADMIN_ALLOW_LIST" preview
  vercel_env GITHUB_CLIENT_ID "$PROD_GITHUB_CLIENT_ID" preview
  vercel_env GITHUB_CLIENT_SECRET "$PROD_GITHUB_CLIENT_SECRET" preview sensitive
  vercel_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID" preview
  vercel_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET" preview sensitive
  vercel_env APPLE_CLIENT_ID "$APPLE_CLIENT_ID" preview
  vercel_env APPLE_CLIENT_SECRET "$APPLE_CLIENT_SECRET" preview sensitive
fi
pause "Press Enter to continue"

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Check it by hand"
say "Vercel reads new variables only on a new deployment. Production picks them up on"
say "the next deploy of main (Actions → Deploy → Run workflow, or gh workflow run deploy.yml --ref main)."
say ""
say "Once it's deployed, open $PROD_URL/en/sign-in:"
step "Sign in with Google → back on the Sign-in page, signed in as your Google email. Sign out."
step "Sign in with Apple, with an Apple ID using the same email (not 'Hide My Email')"
note "    → the same Account, signed in as that email. Sign out."
step "Open a Surah signed out: it reads as before, and DevTools → Application → Cookies shows none set."
step "The plain Sign-in page offers Google and Apple, never GitHub."
say ""
say "Then, in a fresh private window, open $PROD_URL/admin:"
step "You land on the Sign-in page's Admin entry, offering GitHub too. Sign in with GitHub as an"
note "    allow-listed email → back at /admin, the Surah picker named as you. Sign out."
step "Sign in with GitHub as an email not on the list → refused, no Account made."
note "    Old settings from the hand-written Admin sign-in (AUTH_*) can be removed from Vercel."
say ""
say "Locally, restart 'pnpm dev' so it picks up $ENV_FILE, then try Google at $LOCAL_URL/en/sign-in."
note "    Apple only works on production. 'Sign-in didn't start' means that method isn't set up there."
if confirm "Open $PROD_URL/en/sign-in now?"; then open_url "$PROD_URL/en/sign-in"; fi
pause "Press Enter to finish"

finish
(( ${#VERCEL_ENVS[@]} )) && note "set ${#VERCEL_ENVS[@]} Vercel variable(s): ${VERCEL_ENVS[*]}"
printf '\n'
